<script>
document.addEventListener('DOMContentLoaded',()=>{
  const propertyModal=document.getElementById('propertyModal');
  const levelTypes=new Set(['floor','ground_floor','basement','mezzanine','terrace','roof','technical_floor']);
  const toggleLevelFields=()=>{const isLevel=levelTypes.has(document.getElementById('propertyType')?.value||'');document.getElementById('propertyFloorWrap').hidden=!isLevel;document.getElementById('propertyLevelOrderWrap').hidden=!isLevel;};
  const syncRoleDefaults=(force=false)=>{const role=document.getElementById('propertyRole')?.value||'physical';const accepts=document.getElementById('propertyAcceptsResources'),resident=document.getElementById('propertyResidentVisible'),ops=document.getElementById('propertyOperationsVisible');if(force){if(accepts)accepts.checked=role!=='organizer';if(resident)resident.checked=role!=='organizer';if(ops)ops.checked=true;}};
  propertyModal?.addEventListener('show.bs.modal',event=>{const b=event.relatedTarget;const edit=b?.classList.contains('js-edit-property');document.getElementById('propertyModalTitle').textContent=edit?'Editar elemento':'Nuevo elemento de estructura';const values={propertyId:edit?b.dataset.id:'',propertyCode:edit?b.dataset.code:'',propertyName:edit?b.dataset.name:'',propertyRole:edit?b.dataset.role:'physical',propertyType:edit?b.dataset.type:'site',propertyParent:edit?b.dataset.parent:'',propertyFloor:edit?b.dataset.floor:'',propertyLevelOrder:edit?b.dataset.levelOrder:'',propertyStatus:edit?b.dataset.status:'active'};Object.entries(values).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value??'';});document.getElementById('propertyAcceptsResources').checked=edit?b.dataset.acceptsResources==='1':true;document.getElementById('propertyOperationsVisible').checked=edit?b.dataset.operationsVisible==='1':true;document.getElementById('propertyResidentVisible').checked=edit?b.dataset.residentVisible==='1':true;toggleLevelFields();if(!edit)syncRoleDefaults(true);});
  document.getElementById('propertyType')?.addEventListener('change',toggleLevelFields);document.getElementById('propertyRole')?.addEventListener('change',()=>syncRoleDefaults(true));
  const depModal=document.getElementById('propertyDependenciesModal');
  depModal?.addEventListener('show.bs.modal',event=>{
    const b=event.relatedTarget;if(!b)return;
    let children=[],areas=[],counts={};try{children=JSON.parse(b.dataset.children||'[]')}catch(e){}try{areas=JSON.parse(b.dataset.areas||'[]')}catch(e){}try{counts=JSON.parse(b.dataset.counts||'{}')}catch(e){}
    const id=String(b.dataset.id||''),parent=String(b.dataset.parent||''),parentName=b.dataset.parentName||'Raíz de la instalación';
    document.getElementById('depPropertyName').textContent=`${b.dataset.name||'Elemento'} · Contenedor actual bajo: ${parentName}`;document.getElementById('depDeleteId').value=id;
    const cards=document.getElementById('depCountCards');cards.innerHTML='';const labels={children:'Subelementos',areas:'Áreas/espacios',devices:'Activos directos',people:'Personas',access:'Accesos',cameras:'Cámaras'};Object.entries(labels).forEach(([k,label])=>{const n=Number(counts[k]||0);if(!n)return;const c=document.createElement('div');c.className='col-6 col-md-4';c.innerHTML=`<div class="border rounded-3 p-2 h-100"><strong class="d-block">${n}</strong><small class="text-body-secondary">${label}</small></div>`;cards.appendChild(c);});
    const cs=document.getElementById('depChildrenSection'),cl=document.getElementById('depChildrenList'),ci=document.getElementById('depChildInputs'),ct=document.getElementById('depChildrenTarget');cs.hidden=!children.length;cl.innerHTML='';ci.innerHTML='';children.forEach(x=>{const a=document.createElement('a');a.className='list-group-item list-group-item-action d-flex justify-content-between align-items-center gap-2';a.href='<?=url('structure-context')?>&id='+encodeURIComponent(x.id);a.innerHTML=`<span><strong>${escapeHtml(x.name||'')}</strong><small class="d-block text-body-secondary">${escapeHtml(x.code||'')} · ${escapeHtml(x.property_type||'')}</small></span><span class="badge text-bg-light">orden ${Number(x.level_order??0)}</span>`;cl.appendChild(a);const inp=document.createElement('input');inp.type='hidden';inp.name='selected_ids[]';inp.value=x.id;ci.appendChild(inp);});if(ct){Array.from(ct.options).forEach(o=>o.disabled=o.value===id);ct.value=parent;}
    const as=document.getElementById('depAreasSection'),al=document.getElementById('depAreasList'),ai=document.getElementById('depAreaInputs'),at=document.getElementById('depAreasTarget');as.hidden=!areas.length;al.innerHTML='';ai.innerHTML='';areas.forEach(x=>{const a=document.createElement('a');a.className='list-group-item list-group-item-action';a.href='<?=url('area-context')?>&id='+encodeURIComponent(x.id);a.innerHTML=`<strong>${escapeHtml(x.name||'')}</strong><small class="d-block text-body-secondary">${escapeHtml(x.code||'')} · ${escapeHtml(x.scope_type||'common')} · ${escapeHtml(x.usage_type||'general')}</small>`;al.appendChild(a);const inp=document.createElement('input');inp.type='hidden';inp.name='selected_ids[]';inp.value=x.id;ai.appendChild(inp);});if(at){Array.from(at.options).forEach(o=>o.disabled=o.value===id);at.value=parent;}
    const other=Number(counts.devices||0)+Number(counts.people||0);const warn=document.getElementById('depOtherWarning');warn.hidden=other===0;if(other>0)warn.innerHTML='<strong>Aún hay relaciones directas que revisar.</strong> '+(Number(counts.devices||0)?`${Number(counts.devices)} activo(s) directamente ubicados aquí. `:'')+(Number(counts.people||0)?`${Number(counts.people)} persona(s) vinculadas directamente. `:'')+'Muévelas o desvincúlalas antes de una eliminación definitiva.';
  });
  const escapeHtml=v=>String(v??'').replace(/[&<>"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));

  const duplicateModal=document.getElementById('duplicatePropertyModal');
  duplicateModal?.addEventListener('show.bs.modal',event=>{const b=event.relatedTarget;if(!b)return;document.getElementById('duplicateSourceId').value=b.dataset.id||'';document.getElementById('duplicateSourceLabel').textContent=`Origen: ${b.dataset.name||''} (${b.dataset.code||''})`;document.getElementById('duplicateCode').value=`${b.dataset.code||'COPIA'}-COPIA`;document.getElementById('duplicateName').value=`${b.dataset.name||'Estructura'} copia`;document.getElementById('duplicateParent').value=b.dataset.parent||'';});

  const checks=[...document.querySelectorAll('.js-property-select')],selectPage=document.getElementById('selectPage'),toolbar=document.getElementById('bulkToolbar'),count=document.getElementById('bulkSelectedCount'),bulkModalEl=document.getElementById('bulkPropertyModal'),bulkModal=bulkModalEl?new bootstrap.Modal(bulkModalEl):null,form=document.getElementById('bulkPropertyForm'),submit=document.getElementById('bulkSubmitButton'),status=document.getElementById('bulkSubmitStatus');
  const titles={move:'Mover elementos',status:'Cambiar estado',type:'Cambiar tipo',rename:'Renombrar elementos',delete:'Eliminar elementos'};
  const helps={move:'Se conserva la jerarquía interna de las ramas seleccionadas.',status:'El estado se aplicará a todos los registros seleccionados.',type:'Corrige el tipo sin cambiar su ubicación.',rename:'Las reglas se validan antes de guardar.',delete:'Los elementos con actividad real se desactivan; no se destruye el historial.'};
  const selectedIds=()=>checks.filter(c=>c.checked).map(c=>c.value);
  const updateSelection=()=>{const selected=selectedIds();if(toolbar)toolbar.hidden=!selected.length;if(count)count.textContent=`${selected.length} seleccionado${selected.length===1?'':'s'}`;if(selectPage){selectPage.checked=checks.length>0&&selected.length===checks.length;selectPage.indeterminate=selected.length>0&&selected.length<checks.length;}};
  checks.forEach(c=>c.addEventListener('change',updateSelection));
  selectPage?.addEventListener('change',()=>{checks.forEach(c=>c.checked=selectPage.checked);updateSelection();});
  document.getElementById('bulkClear')?.addEventListener('click',()=>{checks.forEach(c=>c.checked=false);updateSelection();});
  document.querySelectorAll('.js-open-bulk').forEach(button=>button.addEventListener('click',()=>{const selected=selectedIds();if(!selected.length)return;const action=button.dataset.action||'';document.getElementById('bulkAction').value=action;document.getElementById('bulkModalTitle').textContent=titles[action]||'Acción masiva';document.getElementById('bulkModalCount').textContent=`${selected.length} elemento${selected.length===1?'':'s'} seleccionado${selected.length===1?'':'s'}`;document.getElementById('bulkModalHelp').textContent=helps[action]||'';document.querySelectorAll('.js-bulk-section').forEach(section=>section.hidden=section.dataset.section!==action);const container=document.getElementById('bulkSelectedInputs');container.innerHTML='';selected.forEach(id=>{const input=document.createElement('input');input.type='hidden';input.name='selected_ids[]';input.value=id;container.appendChild(input);});document.getElementById('bulkConfirmDelete').checked=false;submit.className=action==='delete'?'btn btn-danger':'btn btn-primary';submit.textContent=action==='delete'?'Eliminar o desactivar':'Aplicar acción';status.textContent='';bulkModal?.show();}));
  form?.addEventListener('submit',event=>{const action=document.getElementById('bulkAction').value;if(!selectedIds().length){event.preventDefault();status.textContent='No hay elementos seleccionados.';return;}if(action==='delete'&&!document.getElementById('bulkConfirmDelete').checked){event.preventDefault();status.textContent='Debes confirmar la eliminación.';document.getElementById('bulkConfirmDelete').focus();return;}submit.disabled=true;submit.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Procesando…';status.textContent='Enviando la operación al servidor.';});
  updateSelection();
});
</script>
<?php endif;?>
